tags: [decorator, gof, delegation, self-calls]
code:
  language: csharp
  harness: statements
  source: |
    var inner = new InMemoryRepository();
    var counting = new CountingRepository(inner);
    IRepository repo = counting;

    repo.GetAll();

    Console.Write($"{counting.GetCalls} {inner.GetCalls}");

    interface IRepository
    {
        string Get(int id);
        List<string> GetAll();
    }

    class InMemoryRepository : IRepository
    {
        public int GetCalls;

        public string Get(int id)
        {
            GetCalls++;
            return $"item{id}";
        }

        public List<string> GetAll()
        {
            var items = new List<string>();
            for (int id = 1; id <= 3; id++)
            {
                items.Add(Get(id));
            }
            return items;
        }
    }

    class CountingRepository : IRepository
    {
        private readonly IRepository _inner;
        public int GetCalls;

        public CountingRepository(IRepository inner) => _inner = inner;

        public string Get(int id)
        {
            GetCalls++;
            return _inner.Get(id);
        }

        public List<string> GetAll() => _inner.GetAll();
    }
